import{_ as t,o,c as d,a2 as a}from"./chunks/framework.C9_66ieh.js";const m=JSON.parse('{"title":"Agents","description":"","frontmatter":{},"headers":[],"relativePath":"agents.md","filePath":"agents.md","lastUpdated":1785285564000}'),s={name:"agents.md"};function n(c,e,r,l,i,p){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h1><p>TrueDeck runs <strong>CLI coding agents</strong> in PTY sessions. It does not embed model SDKs; each agent is an external binary resolved on disk / <code>PATH</code>.</p><h2 id="built-in-presets" tabindex="-1">Built-in presets <a class="header-anchor" href="#built-in-presets" aria-label="Permalink to &quot;Built-in presets&quot;">​</a></h2><p>Defaults live in <code>electron/main/agents.ts</code> (merged with <code>agents.json</code> so new defaults always appear):</p><table tabindex="0"><thead><tr><th>Id</th><th>Name</th><th>Command</th><th>Install (typical)</th></tr></thead><tbody><tr><td><code>grok</code></td><td>Grok</td><td><code>grok</code></td><td><code>npm install -g @xai/grok</code></td></tr><tr><td><code>codex</code></td><td>Codex</td><td><code>codex</code></td><td><code>npm install -g @openai/codex</code></td></tr><tr><td><code>cursor</code></td><td>Cursor Agent</td><td><code>cursor-agent</code></td><td>Windows: <code>irm https://cursor.com/install?win=1 | iex</code> · Unix: <code>curl https://cursor.com/install -fsS | bash</code></td></tr><tr><td><code>claude</code></td><td>Claude</td><td><code>claude</code></td><td>Windows: Claude install.ps1 · Unix: install.sh</td></tr><tr><td><code>gemini</code></td><td>Gemini</td><td><code>gemini</code></td><td><code>npm install -g @google/gemini-cli</code></td></tr><tr><td><code>shell</code></td><td>Shell</td><td><code>powershell.exe</code> / <code>$SHELL</code></td><td>Built-in</td></tr><tr><td><code>opencode</code></td><td>OpenCode</td><td><code>opencode</code></td><td><code>npm install -g opencode-ai</code></td></tr><tr><td><code>aider</code></td><td>Aider</td><td><code>aider</code></td><td><code>pip install aider-chat</code></td></tr></tbody></table><p>Each preset has <code>color</code>, <code>icon</code>, <code>description</code>, and <code>installCommand</code> for UI hints when present.</p><p>User overrides in <code>agents.json</code> may change names/colors; <strong>command / args / install for built-ins prefer defaults</strong> so the CLI-only Cursor policy stays enforced.</p><h2 id="cli-only-policy-cursor-ide-blocked" tabindex="-1">CLI-only policy (Cursor IDE blocked) <a class="header-anchor" href="#cli-only-policy-cursor-ide-blocked" aria-label="Permalink to &quot;CLI-only policy (Cursor IDE blocked)&quot;">​</a></h2><p>TrueDeck <strong>never launches Cursor IDE</strong> (or VS Code) as an agent.</p><table tabindex="0"><thead><tr><th>Allowed</th><th>Blocked</th></tr></thead><tbody><tr><td><code>cursor-agent</code> under <code>%LOCALAPPDATA%\\cursor-agent\\…</code></td><td><code>Cursor.exe</code>, IDE <code>cursor.cmd</code> under Program Files</td></tr><tr><td><code>node.exe</code> + <code>index.js</code> from a cursor-agent version dir</td><td>Paths matching <code>isIdeBinary()</code> in <code>resolve-command.ts</code></td></tr><tr><td>PATH entries that clearly are <code>cursor-agent</code></td><td>Bare <code>cursor</code> command name</td></tr></tbody></table><p>Hard blocks also exist at spawn time in <code>pty-manager.ts</code> if resolve slipped:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Blocked: Cursor IDE cannot be spawned. Use cursor-agent CLI only.</span></span></code></pre></div><h3 id="how-cursor-agent-is-resolved" tabindex="-1">How Cursor Agent is resolved <a class="header-anchor" href="#how-cursor-agent-is-resolved" aria-label="Permalink to &quot;How Cursor Agent is resolved&quot;">​</a></h3><p><code>resolveCursorAgent()</code> prefers:</p><ol><li>Newest <code>%LOCALAPPDATA%\\cursor-agent\\versions\\&lt;ver&gt;\\</code> with <code>node.exe</code> + <code>index.js</code></li><li>Root <code>cursor-agent</code> install layout</li><li>PATH <code>cursor-agent</code> only if the path is clearly the agent (not IDE)</li></ol><p>If missing, <code>available: false</code> and the install one-liner is shown in the palette.</p><h2 id="command-resolve" tabindex="-1">Command resolve <a class="header-anchor" href="#command-resolve" aria-label="Permalink to &quot;Command resolve&quot;">​</a></h2><p><code>resolveAgentCommand(agentId, command, args)</code> (<code>electron/main/resolve-command.ts</code>):</p><ol><li>Special-case <code>cursor</code> → <code>resolveCursorAgent</code></li><li>Special-case <code>shell</code> → PowerShell / bash</li><li>Reject IDE binaries</li><li>Absolute path if it exists</li><li><code>where.exe</code> / <code>which</code> on PATH (Windows prefers <code>.cmd</code> then <code>.exe</code>)</li><li>Known locations (npm global, nvm4w, <code>~/.grok/bin</code>, <code>~/.local/bin</code>, …)</li></ol><p>Results are cached ~5 minutes (<code>whichCache</code> / <code>resolveCache</code>). Palette probes force a fresh resolve per agent.</p><h2 id="spawn-path" tabindex="-1">Spawn path <a class="header-anchor" href="#spawn-path" aria-label="Permalink to &quot;Spawn path&quot;">​</a></h2><p>When you pick an agent or dispatch a task:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UI / task-dispatch</span></span>
<span class="line"><span> → load agent preset</span></span>
<span class="line"><span> → resolveAgentCommand</span></span>
<span class="line"><span> → memory env (TRUEDECK_*)</span></span>
<span class="line"><span> → maybeWrapAgentFrame (when agent frame is enabled)</span></span>
<span class="line"><span> → PtyManager.spawn (rust or node-pty)</span></span>
<span class="line"><span> → SessionInfo to renderer</span></span></code></pre></div><p>Environment always includes (among others):</p><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>TRUEDECK</code></td><td><code>1</code></td></tr><tr><td><code>TRUEDECK_AGENT</code></td><td>Agent id</td></tr><tr><td><code>TRUEDECK_PROJECT</code></td><td>Project root (cwd)</td></tr><tr><td><code>TRUEDECK_RESOLVED</code></td><td>Resolve source label (+ <code>+frame</code> if framed)</td></tr><tr><td><code>TRUEDECK_PTY</code></td><td>Backend id (<code>rust</code> / node)</td></tr><tr><td><code>TERM</code> / <code>COLORTERM</code> / <code>TERM_PROGRAM</code></td><td>Terminal identity for agent TUIs</td></tr></tbody></table><p>Task dispatch adds <code>TRUEDECK_TASK</code>, <code>TRUEDECK_TASK_FILE</code>, <code>TRUEDECK_TASK_TITLE</code>, <code>TRUEDECK_TASK_IDEA</code>. See <a href="./task-board">Task board</a>.</p><p>If the CLI is missing, spawn throws with the install hint.</p><h2 id="agent-palette" tabindex="-1">Agent palette <a class="header-anchor" href="#agent-palette" aria-label="Permalink to &quot;Agent palette&quot;">​</a></h2><p><strong>Ctrl+T</strong> opens the palette (requires an open project). Entries can show probe availability (<code>available</code>, <code>resolvedFrom</code>, <code>installCommand</code>). Installing a CLI outside TrueDeck is required for non-shell agents.</p><h2 id="custom-command-sessions" tabindex="-1">Custom / command sessions <a class="header-anchor" href="#custom-command-sessions" aria-label="Permalink to &quot;Custom / command sessions&quot;">​</a></h2><ul><li><strong>On-open commands</strong> and ad-hoc project commands spawn as <code>kind: &#39;command&#39;</code> with synthetic agent ids like <code>cmd-…</code></li><li>Command panes are <strong>not</strong> wrapped in the agent frame by default (same rule as shell unless <code>frameShellPanes</code> is on)</li></ul><h2 id="reset-presets" tabindex="-1">Reset presets <a class="header-anchor" href="#reset-presets" aria-label="Permalink to &quot;Reset presets&quot;">​</a></h2><p>Settings → Agents can reset agents to defaults (<code>getDefaultAgents</code> / save). Use this if <code>agents.json</code> drifts.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./agent-frame">Agent frame</a></li><li><a href="./configuration">Configuration</a></li><li><a href="./troubleshooting#cursor-ide-blocked-or-cursor-agent-missing">Troubleshooting</a></li></ul>`,35)])])}const g=t(s,[["render",n]]);export{m as __pageData,g as default};
